-- M179-06.filter_thickness
update public.fields set verification_status='verified_against_standard', verification_quote='Bei einer minimalen Filtermächtigkeit von $0,2 \mathrm{~m}$ und gleicher Überstauhöhe ergeben sich hieraus Filtergeschwindigkeiten zwischen $0,27 \mathrm{~m} / \mathrm{h}$ und $2,7 \mathrm{~m} / \mathrm{h}$. | Eine Filtermächtigkeit $<0,2 \mathrm{~m}$ sowie eine Filtergeschwindigkeit $>2,5 \mathrm{~m} / \mathrm{h}$ führen zu einem deutlich höheren Versagensrisiko und einer deutlich geringeren Wirksamkeit der Anlagen und werden daher nicht empfohlen. — printed p.21', verification_note='md-verified 2026-09-05 (§7.3.2, printed p.21) [VC]', verified_at=now() where id='0c1a3124-2c9a-44bf-b610-96d99f705ad4' and verification_status not in ('verified_against_standard','corrected');
-- M179-06.sludge_storage_min
update public.fields set verification_status='verified_against_standard', verification_quote='Bei Sedimentationsanlagen ist zusätzlich zum Sedimentationsraum ein Schlammspeicher von $\geqslant 15 \mathrm{~kg} /\left(\mathrm{m}^{2} \cdot \mathrm{a}\right)$ AFS vorzusehen. | Bei der Sedimentation werden maximale Rückhaltemengen an AFS von $15 \mathrm{~kg} /\left(\mathrm{m}^{2} \cdot \mathrm{a}\right)$ bezogen auf die Sedimentationsfläche festgelegt, um einen sachgemäßen Betrieb zu ermöglichen (Entleerung ca. 1-mal pro Jahr). — printed p.23 (§8.2) und p.31 (A.2.1)', verification_note='md-verified 2026-09-05 (§8.2; Anhang A.2.1, printed p.23 (§8.2) und p.31 (A.2.1)) [VC]', verified_at=now() where id='fad7af95-df0b-41dc-8dd1-15530eb2f67b' and verification_status not in ('verified_against_standard','corrected');
-- M179-06.sludge_density
update public.fields set verification_status='verified_against_standard', verification_quote='Bei der Schlammvolumenermittlung kann eine Dichte von $2,0 \mathrm{~g} / \mathrm{cm}^{3}$ angesetzt werden. Über den Schlammspeicher muss sichergestellt werden, dass die Jahresfeststofffracht in der Anlage zwischengespeichert werden kann. — printed p.23', verification_note='md-verified 2026-09-05 (§8.2, printed p.23) [VC]', verified_at=now() where id='47d965b0-71e7-4972-b5c7-c18cb4f456a9' and verification_status not in ('verified_against_standard','corrected');
-- M179-06.filter_AFS63_max_load
update public.fields set verification_status='verified_against_standard', verification_quote='Die hydraulische und stoffliche Leistungsfähigkeit eines Filtrationsverfahrens sollte bei einer AFS63-Belastung $\leqslant 7 \mathrm{~kg} /\left(\mathrm{m}^{2} \cdot \mathrm{a}\right)$ (maximale Filterflächenbelastung, siehe auch Berechnungsbeispiele in Anhang A) ohne Wartungs- und Reinigungsaufwand für mindestens 12 Monate sichergestellt sein. | Für die so ermittelte Filterfläche sollte eine Filterflächenbelastung von $7 \mathrm{~kg} /\left(\mathrm{m}^{2} \cdot \mathrm{a}\right)$ AFS63 nicht überschritten werden. Ist die rechnerische Belastung höher, ist eine größere Filterfläche zu wählen. — printed p.21 (§7.3.2) und p.23 (§8.2)', verification_note='md-verified 2026-09-05 (§7.3.2; §8.2, printed p.21 (§7.3.2) und p.23 (§8.2)) [VC]', verified_at=now() where id='85ef3eb1-7edd-4f17-8b86-bd48c234cad2' and verification_status not in ('verified_against_standard','corrected');
-- M179-06.filter_type
update public.fields set verification_status='verified_against_standard', verification_quote='In Abhängigkeit von der gewählten Filtergeschwindigkeit $v_{F}$ kann zwischen Raum- und Oberflächenfiltration unterschieden werden. | Bei der Raumfiltration werden partikuläre Stoffe im Porenraum des Filtermaterials zurückgehalten. | Zur Niederschlagswasserbehandlung wird die Oberflächenfiltration empfohlen. — printed p.16', verification_note='md-verified 2026-09-05 (§6.2.3, printed p.16) [VC]', verified_at=now() where id='4123b9c0-8900-4713-962c-85c417e4d659' and verification_status not in ('verified_against_standard','corrected');

