update public.fields set verification_status='verified_against_standard', verification_quote='SUMME:} & \\ | Unter Standardbedingungen (Summe der standortspezifischen Einflüsse $\leqslant 1$ ) wird eine Standzeit der Anlagen von mindestens einem Jahr bzw. ein Reinigungsintervall von maximal einmal pro Jahr vorausgesetzt. Für höhere Summenwerte gilt: | Summenwert 1: Erhöhter Schlammanfall → erhöhter Aufwand im Betrieb (z. B. häufigere Reinigungsintervalle notwendig), | Summenwert $\geqslant 3$ : Sehr hoher Schlammanfall → mangelnde Betriebssicherheit der Anlage. — printed p.24–25', verification_note='md-verified 2026-09-05 (§8.3 Tab. 6 (Ende) + Folgetext, printed p.24–25) [VC]', verified_at=now() where id='baa3d3ea-8a66-4996-9e82-13712a25fa12' and verification_status not in ('verified_against_standard','corrected');

-- ===== M179-15 =====
-- M179-15.treatment_method_final
update public.fields set verification_status='verified_against_standard', verification_quote='Feststoffe (u. a. AFS63) werden mechanisch-physikalisch (z. B. durch Dichtetrennung oder Filtration) zurückgehalten. | Gelöste Schadstoffe werde meist durch eine Kombination chemisch-physikalischer Verfahren (z. B. Adsorption, Ionenaustausch oder Fällung mit Filtration) zurückgehalten. — printed p.15 (§6.2.1) und p.31 (A.1)', verification_note='md-verified 2026-09-05 (§6.2.1; Anhang A.1, printed p.15 (§6.2.1) und p.31 (A.1)) [VC] — Duplikat-Feld von M179-05.treatment_method (Bemessungs-Zusammenfassung)', verified_at=now() where id='ce22691a-0e56-414c-83e1-0c655264be3c' and verification_status not in ('verified_against_standard','corrected');
-- M179-15.A_F_final
update public.fields set verification_status='verified_against_standard', verification_quote='$A_{\text {F }}$ & $\mathrm{m}^{2}$ & Filterfläche | Langjährige Erfahrungen aus der zentralen und dezentralen Anwendung von Filtrationsverfahren ohne wirksame Vorbehandlung zeigen, dass über ein festgelegtes Verhältnis zwischen Filterfläche und angeschlossener befestigter Flächen (Filterflächenverhältnis von $1 \%$, siehe Gleichung 5 ) eine einfache und gleichzeitig betriebsstabile Auslegung möglich ist. — printed p.11 (Tab. 2) und p.23 (§8.2)', verification_note='md-verified 2026-09-05 (Tab. 2; §8.2, printed p.11 (Tab. 2) und p.23 (§8.2)) [VC] — Duplikat-Feld von M179-12.A_F (Bemessungs-Zusammenfassung)', verified_at=now() where id='c07e61e5-fce7-4b4e-8d7f-d7193719019b' and verification_status not in ('verified_against_standard','corrected');
-- M179-15.A_sed_final
update public.fields set verification_status='verified_against_standard', verification_quote='$A_{\text {sed }}$ & $\mathrm{m}^{2}$ & sedimentationswirksame Fläche | Sedimentationsanlagen: Auf dieser Grundlage kann die erforderliche sedimentationswirksame Oberfläche ( $A_{\text {sed }}$ ) als Grundfläche der Anlage oder als projizierte Fläche unterhalb von Schrägklärern gemäß (4) bestimmt werden. — printed p.11 (Tab. 2) und p.23 (§8.2)', verification_note='md-verified 2026-09-05 (Tab. 2; §8.2, printed p.11 (Tab. 2) und p.23 (§8.2)) [VC] — Duplikat-Feld von M179-11.A_sed (Bemessungs-Zusammenfassung)', verified_at=now() where id='8049a204-8fda-458a-aeba-99b80a65cd0c' and verification_status not in ('verified_against_standard','corrected');
-- M179-15.V_S_final
update public.fields set verification_status='verified_against_standard', verification_quote='Bei Sedimentationsanlagen ist zusätzlich zum Sedimentationsraum ein Schlammspeicher von $\geqslant 15 \mathrm{~kg} /\left(\mathrm{m}^{2} \cdot \mathrm{a}\right)$ AFS vorzusehen. | Bei der Schlammvolumenermittlung kann eine Dichte von $2,0 \mathrm{~g} / \mathrm{cm}^{3}$ angesetzt werden. Über den Schlammspeicher muss sichergestellt werden, dass die Jahresfeststofffracht in der Anlage zwischengespeichert werden kann. — printed p.23', verification_note='md-verified 2026-09-05 (§8.2, printed p.23) [VC] — Das Merkblatt druckt kein Formelzeichen V_S in Tabelle 2; die Quelle definiert den Schlammspeicher über die flächenbezogene AFS-Menge und die Dichteannahme — Symbol-Findung im STAGED-File', verified_at=now() where id='ca6839d2-e1fa-44bf-bbbb-e8268725e9b0' and verification_status not in ('verified_against_standard','corrected');

-- ===== M179-16 =====
-- M179-16.kontrolle_frequency
update public.fields set verification_status='verified_against_standard', verification_quote='Im Beispiel muss die Anlage 1 - bis 2 -mal im Jahr kontrolliert werden. | Die Kontrolle einer Regenwasserbehandlungsanlage ist als Sichtprüfung zu verstehen. Sie dient dabei der Feststellung und Beurteilung des Ist-Zustands der Anlage. Hierbei wird die Anlage durch das Betriebspersonal in Augenschein genommen. Erfasst werden sollten hierbei der Feststoffanfall (z. B. Schlammspiegelmessung), die Prüfung der hydraulischen Durchlässigkeit (z. B. Infiltrationsversuch), die vorhandene Abflussaufteilung und der allgemeine bauliche Zustand. — printed p.27–28', verification_note='md-verified 2026-09-05 (§9 (Bild-5-Beispiel), printed p.27–28) [VC]', verified_at=now() where id='4fab0058-d22f-4f26-b2e0-7575a2f86079' and verification_status not in ('verified_against_standard','corrected');
-- M179-16.reinigung_frequency
update public.fields set verification_status='verified_against_standard', verification_quote='1-mal im Jahr eine Reinigung durchzuführen ist und ca. alle 3 Jahre Teile der Anlage im Rahmen einer Wartung ersetzt werden müssen. | Die Reinigung umfasst die Entnahme und fachgerechte Entsorgung oder Verwertung der zurückgehaltenen Stoffe. Die Anlage wird hinsichtlich Reinigungsleistung und Durchlässigkeit wieder in einen betriebsbereiten Zustand versetzt. — printed p.27–28', verification_note='md-verified 2026-09-05 (§9 (Bild-5-Beispiel), printed p.27–28) [VC]', verified_at=now() where id='1da4265d-a978-4944-a8ee-fda423a07880' and verification_status not in ('verified_against_standard','corrected');
-- M179-16.wartung_frequency
update public.fields set verification_status='verified_against_standard', verification_quote='1-mal im Jahr eine Reinigung durchzuführen ist und ca. alle 3 Jahre Teile der Anlage im Rahmen einer Wartung ersetzt werden müssen. | Bei der Wartung wird der technische Funktionszustand der Anlage wiederhergestellt. Sie umfasst Einstell- und Reinigungsarbeiten sowie den geplanten Austausch von Verschleißteilen. Außerdem gehört zur Wartung das Auffüllen und Austauschen von Verbrauchsstoffen (Filtermaterial, Dichtungen etc.) sowie die sachgerechte Entsorgung der entnommenen Stoffe. — printed p.27–28', verification_note='md-verified 2026-09-05 (§9 (Bild-5-Beispiel), printed p.27–28) [VC]', verified_at=now() where id='f211081c-3a7b-4b07-bc95-004cc6634b11' and verification_status not in ('verified_against_standard','corrected');
-- M179-16.monitoring_planned
update public.fields set verification_status='verified_against_standard', verification_quote='Ist beabsichtigt Erkenntnisse zur Wirksamkeit des Anlagerns zu erheben, empfiehlt sich ein Monitoring von mindestens einem Jahr. — printed p.28', verification_note='md-verified 2026-09-05 (§9, printed p.28) [VC]', verified_at=now() where id='6ef9271b-f4bd-4b6f-bce6-47111a3d2dd9' and verification_status not in ('verified_against_standard','corrected');
