-- M179-16.wartungsvertrag_present
update public.fields set verification_status='verified_against_standard', verification_quote='Bei komplizierten Anlagen, insbesondere bei privaten Betreibern, wird der Abschluss von Wartungsverträgen empfohlen. — printed p.27', verification_note='md-verified 2026-09-05 (§9, printed p.27) [VC]', verified_at=now() where id='8dce678e-7d7f-4468-a9c1-3ccb51b0fa58' and verification_status not in ('verified_against_standard','corrected');
