-- M179-16.betriebsanweisung_status
update public.fields set verification_status='verified_against_standard', verification_quote='Für eine dezentrale Anlage zur Niederschlagswasserbehandlung sind bereits in der Planungsphase eine Betriebs- und gegebenenfalls eine Dienstanweisung zu erstellen. | Maßgebliche Inhalte für Anlagen im Sinne dieses Merkblatts sind in der Arbeitsblattreihe DWA-A 199 „Dienst- und Betriebsanweisung für das Personal von Abwasseranlagen“ in Teil 1 und 2 geregelt. — printed p.26', verification_note='md-verified 2026-09-05 (§8.4.4, printed p.26) [VC]', verified_at=now() where id='c003bcfe-7120-4b5b-9b8a-fecfa5398fbf' and verification_status not in ('verified_against_standard','corrected');

-- ===== M179-17 =====
-- M179-17.eta_ges_achieved
update public.fields set verification_status='verified_against_standard', verification_quote='$\eta_{\text {ges }}$ & \% & Gesamtwirkungsgrad des Stoffrückhalts der Behandlungsanlage | Die nachfolgenden Ausführungen zu verfahrenstechnischen Aspekten sollen sicherstellen, dass der erforderliche Gesamtwirkungsgrad an AFS63 nach Arbeitsblatt DWA-A 102-2 (entspricht $\eta_{\text {ges }}$ ) eingehalten wird. — printed p.11 (Tab. 2) und p.17 (§7.1)', verification_note='md-verified 2026-09-05 (Tab. 2; §7.1, printed p.11 (Tab. 2) und p.17 (§7.1)) [VC]', verified_at=now() where id='e6dedacc-c11e-4b57-9215-8e1d52ef8aec' and verification_status not in ('verified_against_standard','corrected');
-- M179-17.eta_ges_target_met
update public.fields set verification_status='verified_against_standard', verification_quote='Hierzu sind geeignete Verfahren einzusetzen, die je nach Flächenkategorie einen stofflichen Wirkungsgrad $\left(\eta_{\text {ges }}\right)$ von mindestens $47 \%$ (Kategorie II) oder mindestens $63 \%$ (Kategorie III) aufweisen. | Niederschlagsabflüsse der Kategorie I sind nach diesen Vorgaben grundsätzlich nicht behandlungsbedürftig. Für die Kategorie II liegt der erforderliche stoffliche Wirkungsgrad bei $\eta_{\text {ges }} \geqslant 47 \%$; für die Kategorie III bei $\eta_{\text {ges }} \geqslant 63 \%$. — printed p.22 (§8.2) und p.31 (A.2.1)', verification_note='md-verified 2026-09-05 (§8.2; Anhang A.2.1, printed p.22 (§8.2) und p.31 (A.2.1)) [VC]', verified_at=now() where id='536da04a-064c-4b84-9c4c-495dae8749f1' and verification_status not in ('verified_against_standard','corrected');

-- ===== Gleichungen (1)-(5) =====
-- Gleichung (1) — r_krit = 0.1201 * exp(0.0655 * eta_hyd)
update public.equations set verification_status='verified_against_standard', verification_quote='Daher wurden basierend auf Arbeiten von LEUTNANT et al. (2020) die Werte in Tabelle 5 und Gleichung (1) zum Zusammenhang zwischen hydraulischem Wirkungsgrad $\eta_{\text {hyd }}$ und $r_{\text {krit }}$ für dezentrale Anlagen abgeleitet. | r_{\text {krit }}=0,1201 \cdot \mathrm{e}^{\left(0,0655 \cdot n_{\text {hyd }}\right)} \tag{1} | $r_{\text {krit }} \quad$ kritische Regenspende, zur Erreichung des geforderten hydraulischen Wirkungsgrads in l/(s•ha) | $\eta_{\text {hyd }} \quad$ hydraulischer Wirkungsgrad (zu behandeInder Anteil vom Jahresregenabfluss $V_{\text {R,am }}$ in \%) — printed p.17–18', verification_note='md-verified 2026-09-05 (§7.2, Gleichung (1), printed p.17–18) [VC]', verified_at=now() where id='6347746c-e985-4ba3-9520-81ca63df1602' and verification_status <> 'verified_against_standard';
-- Gleichung (2) — eta_hyd = eta_ges / eta_BV
update public.equations set verification_status='verified_against_standard', verification_quote='Unter Berücksichtigung des spezifischen Wirkungsgrads des Behandlungsverfahrens $\left(\eta_{\mathrm{BV}}\right)$ kann gemäß Gleichung $(2)$ der erforderliche hydraulische Wirkungsgrad $\left(\eta_{\text {hyd }}\right)$ berechnet werden. | \eta_{\text {hyd }}=\eta_{\text {ges }} / \eta_{\mathrm{BV}} \tag{2} | $\eta_{\text {hyd }} \quad$ hydraulischer Wirkungsgrad (zu behandeInder Anteil vom Jahresregenabfluss $V_{\text {R,am }}$ in \%) | $\eta_{\text {ges }}$ erforderlicher Gesamtwirkungsgrad gemäß Flächenbilanzierung nach Arbeitsblatt DWAA 102-2 in \% | $\eta_{\mathrm{BV}}$ spezifischer Wirkungsgrad des Behandlungsverfahrens in \% (z. B. Sedimentation $40 \%$ ) — printed p.23', verification_note='md-verified 2026-09-05 (§8.2, Gleichung (2), printed p.23) [VC]', verified_at=now() where id='e8732274-3afd-4123-9842-7154f37845a3' and verification_status <> 'verified_against_standard';
-- Gleichung (3) — Q_krit = A_b_a * Psi_s * r_krit / 10000
update public.equations set verification_status='verified_against_standard', verification_quote='Aus der kritischen Regenspende ( $r_{\text {krit }}$ ), dem Spitzenabflussbeiwert ( $\Psi_{\mathrm{s}}$ ) und der an die Anlagen angeschlossen Fläche ( $A_{\mathrm{b}, \mathrm{a}}$ ) erfolgt nach Gleichung (3) die Berechnung des zu behandelnden, kritischen Abflusses | Q_{\text {krit }}=A_{\mathrm{b}, \mathrm{a}} \cdot \Psi_{\mathrm{s}} \cdot r_{\text {krit }} / 10.000 \tag{3} | $Q_{\text {krit }} \quad$ zu behandelnder kritischer Abfluss in $\mathrm{l} / \mathrm{s}$ | $A_{\mathrm{b}, \mathrm{a}} \quad$ angeschlossene befestigte Fläche in $\mathrm{m}^{2}$ | $\Psi_{\mathrm{s}} \quad$ Spitzenabflussbeiwert im Anwendungsfall dieses Merkblatts mit 1 zu wählen — printed p.23', verification_note='md-verified 2026-09-05 (§8.2, Gleichung (3), printed p.23) [VC]', verified_at=now() where id='829fec47-92c3-40c8-9e51-cfe39086278f' and verification_status <> 'verified_against_standard';
-- Gleichung (4) — A_sed = 3.6 * Q_krit / q_A_max
update public.equations set verification_status='verified_against_standard', verification_quote='Sedimentationsanlagen: Auf dieser Grundlage kann die erforderliche sedimentationswirksame Oberfläche ( $A_{\text {sed }}$ ) als Grundfläche der Anlage oder als projizierte Fläche unterhalb von Schrägklärern gemäß (4) bestimmt werden. | A_{\mathrm{sed}}=3,6 \cdot Q_{\mathrm{krit}} / q_{\mathrm{A}, \max } \tag{4} | $A_{\text {sed }} \quad$ sedimentationswirksame Oberfläche in $\mathrm{m}^{2}$ | $Q_{\text {krit }} \quad$ zu behandelnder kritischer Abfluss in l/s | $q_{A, \max }$ maximale Oberflächenbeschickung des Sedimentationsraums gemäß Bild $4 \mathrm{in} \mathrm{m} / \mathrm{h}$ — printed p.23', verification_note='md-verified 2026-09-05 (§8.2, Gleichung (4), printed p.23) [VC]', verified_at=now() where id='ea01f574-3d48-4ef6-98de-7ee80fe59f53' and verification_status <> 'verified_against_standard';
-- Gleichung (5) — A_F = A_b_a * 0.01
update public.equations set verification_status='verified_against_standard', verification_quote='Langjährige Erfahrungen aus der zentralen und dezentralen Anwendung von Filtrationsverfahren ohne wirksame Vorbehandlung zeigen, dass über ein festgelegtes Verhältnis zwischen Filterfläche und angeschlossener befestigter Flächen (Filterflächenverhältnis von $1 \%$, siehe Gleichung 5 ) eine einfache und gleichzeitig betriebsstabile Auslegung möglich ist. | A_{\mathrm{F}}=A_{\mathrm{b}, \mathrm{a}} \cdot 0,01 \tag{5} | $A_{\mathrm{F}} \quad$ Filterfläche in $\mathrm{m}^{2}$ | $A_{\mathrm{b}, \mathrm{a}}$ befestigte angeschlossene Fläche in $\mathrm{m}^{2}$ — printed p.23', verification_note='md-verified 2026-09-05 (§8.2, Gleichung (5), printed p.23) [VC]', verified_at=now() where id='7b8ec78a-4133-49bb-9c87-804e9e91e257' and verification_status <> 'verified_against_standard';
